"""
benchcode_pip — `pip` for an app whose packages are built in
═════════════════════════════════════════════════════════════

BenchCode ships its Python packages inside the app and works offline; pip
itself is left out of the shipped bundle (it downloads and installs code).
So `pip list`, `pip show` and `pip freeze` — the commands people use to see
what they have — are answered here from the installed distributions'
metadata (importlib.metadata), in pip's own output formats, so a notebook
copied from Colab or a tutorial still works. Commands that would download
(`install`, `download`, `wheel`, …) say in one line why they can't, and
name the packages that are already built in.

Used by the terminal's `pip` (offlinai_shell, when pip isn't importable)
and by the notebook's `pip …`, `!pip …` and `%pip …` lines.

    import benchcode_pip
    rc = benchcode_pip.main(["list"])        # prints, returns an exit code
"""

import json
import os
import re
import sys

_OFFLINE_LINE = "BenchCode's packages come built in and work offline. Library lists every package included."

# Verbs that would reach the internet or change installed code.
_NETWORK_VERBS = {"install", "download", "wheel", "index", "search", "lock"}


def _md():
    import importlib.metadata as md
    return md


def _canon(name: str) -> str:
    """PEP 503 normalised name: 'Scikit_Learn' and 'scikit-learn' match."""
    return re.sub(r"[-_.]+", "-", name or "").lower()


def _user_site() -> str:
    return os.path.expanduser("~/Documents/site-packages")


def _location(dist) -> str:
    try:
        return str(dist.locate_file("")).rstrip("/")
    except Exception:
        return ""


def _is_user_installed(dist) -> bool:
    loc = _location(dist)
    return bool(loc) and ("/Documents/site-packages" in loc or loc.startswith(_user_site()))


def installed():
    """Every installed distribution once, by normalised name: the first
    on sys.path wins, as it would for an import."""
    seen = {}
    for dist in _md().distributions():
        try:
            name = dist.metadata["Name"]
        except Exception:
            name = None
        if not name:
            continue
        key = _canon(name)
        if key not in seen:
            seen[key] = dist
    return seen


def _requirement_names(dist):
    """Names `dist` needs at run time (no extras), markers evaluated for
    this Python where `packaging` is available."""
    out = []
    for raw in (dist.requires or []):
        try:
            from packaging.requirements import Requirement
            req = Requirement(raw)
            if req.marker is not None and not req.marker.evaluate({"extra": ""}):
                continue
            out.append((req.name, req))
        except Exception:
            if "extra ==" in raw or "extra==" in raw:
                continue
            m = re.match(r"\s*([A-Za-z0-9][A-Za-z0-9._-]*)", raw)
            if m:
                out.append((m.group(1), None))
    return out


def _print_table(rows, headers):
    widths = [max(len(str(r[i])) for r in [headers] + rows) for i in range(len(headers))]
    def line(cells):
        return " ".join(str(c).ljust(w) for c, w in zip(cells, widths)).rstrip()
    print(line(headers))
    print(" ".join("-" * w for w in widths))
    for r in rows:
        print(line(r))


# ─── list / freeze ────────────────────────────────────────────────

def _list(args):
    fmt = "columns"
    verbose = False
    user_only = False
    not_required = False
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-o", "--outdated", "-u", "--uptodate"):
            print("pip list %s compares with PyPI, which needs the internet; "
                  "BenchCode works offline." % a)
            return 1
        if a.startswith("--format="):
            fmt = a.split("=", 1)[1]
        elif a == "--format" and i + 1 < len(args):
            fmt = args[i + 1]; i += 1
        elif a in ("-v", "--verbose"):
            verbose = True
        elif a == "--user":
            user_only = True
        elif a == "--not-required":
            not_required = True
        elif a in ("-e", "--editable"):
            return 0          # nothing here is installed in editable mode
        elif a in ("-l", "--local", "--disable-pip-version-check", "--no-color", "-q", "--quiet",
                   "--exclude-editable", "--include-editable"):
            pass
        else:
            sys.stderr.write("ERROR: pip list: no such option: %s\n" % a)
            return 2
        i += 1

    dists = installed()
    items = sorted(dists.items())
    if user_only:
        items = [(k, d) for k, d in items if _is_user_installed(d)]
    if not_required:
        needed = set()
        for d in dists.values():
            needed.update(_canon(n) for n, _ in _requirement_names(d))
        items = [(k, d) for k, d in items if k not in needed]

    if fmt == "freeze":
        for _, d in items:
            print("%s==%s" % (d.metadata["Name"], d.version))
    elif fmt == "json":
        print(json.dumps([{"name": d.metadata["Name"], "version": d.version} for _, d in items]))
    elif fmt == "columns":
        if verbose:
            rows = [(d.metadata["Name"], d.version, _location(d),
                     "pip" if _is_user_installed(d) else "BenchCode") for _, d in items]
            _print_table(rows, ("Package", "Version", "Location", "Installer"))
        else:
            _print_table([(d.metadata["Name"], d.version) for _, d in items], ("Package", "Version"))
    else:
        sys.stderr.write("ERROR: pip list: invalid --format: %s (choose columns, freeze or json)\n" % fmt)
        return 2
    return 0


def _freeze(args):
    for _, d in sorted(installed().items()):
        print("%s==%s" % (d.metadata["Name"], d.version))
    return 0


# ─── show ─────────────────────────────────────────────────────────

def _show(args):
    files = "-f" in args or "--files" in args
    verbose = "-v" in args or "--verbose" in args
    names = [a for a in args if not a.startswith("-")]
    if not names:
        sys.stderr.write("ERROR: Please provide a package name or names.\n")
        return 1
    dists = installed()
    found, missing = [], []
    for n in names:
        d = dists.get(_canon(n))
        (found if d is not None else missing).append(d if d is not None else n)
    if missing:
        sys.stderr.write("WARNING: Package(s) not found: %s\n" % ", ".join(missing))
    required_by = {}
    if found:
        wanted = {_canon(d.metadata["Name"]) for d in found}
        for d in dists.values():
            for n, _ in _requirement_names(d):
                if _canon(n) in wanted:
                    required_by.setdefault(_canon(n), set()).add(d.metadata["Name"])
    for i, d in enumerate(found):
        m = d.metadata
        if i:
            print("---")
        home = m.get("Home-page") or ""
        if not home:
            for pu in (m.get_all("Project-URL") or []):
                label, _, url = pu.partition(",")
                if label.strip().lower() in ("homepage", "home", "source", "repository"):
                    home = url.strip()
                    break
        lic = m.get("License-Expression") or m.get("License") or ""
        lic = lic.strip().splitlines()[0] if lic.strip() else ""
        requires = sorted({n for n, _ in _requirement_names(d)}, key=str.lower)
        print("Name: %s" % m["Name"])
        print("Version: %s" % d.version)
        print("Summary: %s" % (m.get("Summary") or ""))
        print("Home-page: %s" % home)
        print("Author: %s" % (m.get("Author") or ""))
        print("Author-email: %s" % (m.get("Author-email") or ""))
        print("License: %s" % lic)
        print("Location: %s" % os.path.dirname(_location(d) + "/x"))
        print("Requires: %s" % ", ".join(requires))
        print("Required-by: %s" % ", ".join(sorted(required_by.get(_canon(m["Name"]), ()), key=str.lower)))
        if verbose:
            print("Metadata-Version: %s" % (m.get("Metadata-Version") or ""))
            print("Installer: %s" % ("pip" if _is_user_installed(d) else "BenchCode (built in)"))
            cls = m.get_all("Classifier") or []
            print("Classifiers:")
            for c in cls:
                print("  %s" % c)
            eps = list(getattr(d, "entry_points", []) or [])
            print("Entry-points:")
            for ep in eps:
                print("  [%s] %s = %s" % (ep.group, ep.name, ep.value))
        if files:
            print("Files:")
            for f in (d.files or []):
                print("  %s" % f)
    return 1 if missing and not found else 0


# ─── check ────────────────────────────────────────────────────────

def _check(args):
    dists = installed()
    problems = []
    for key, d in sorted(dists.items()):
        for name, req in _requirement_names(d):
            other = dists.get(_canon(name))
            if other is None:
                problems.append("%s %s requires %s, which is not installed."
                                % (d.metadata["Name"], d.version, name))
            elif req is not None and req.specifier and not req.specifier.contains(other.version, prereleases=True):
                problems.append("%s %s has requirement %s%s, but you have %s %s."
                                % (d.metadata["Name"], d.version, name, req.specifier,
                                   other.metadata["Name"], other.version))
    for p in problems:
        print(p)
    if not problems:
        print("No broken requirements found.")
    return 1 if problems else 0


# ─── install and the other network verbs ──────────────────────────

def _requested(args):
    """Package names an install line asks for, from its arguments and any
    -r requirements files, without versions or extras."""
    names = []
    i = 0
    with_value = {"-r", "--requirement", "-c", "--constraint", "-i", "--index-url", "--extra-index-url",
                  "-f", "--find-links", "-t", "--target", "--prefix", "--root", "--platform",
                  "--python-version", "--implementation", "--abi", "--no-binary", "--only-binary",
                  "--report", "--upgrade-strategy", "-d", "--dest", "-w", "--wheel-dir"}
    while i < len(args):
        a = args[i]
        if a in ("-r", "--requirement") and i + 1 < len(args):
            try:
                with open(os.path.expanduser(args[i + 1]), encoding="utf-8") as fh:
                    for line in fh:
                        line = line.split("#", 1)[0].strip()
                        if line and not line.startswith("-"):
                            names.append(line)
            except OSError as e:
                sys.stderr.write("ERROR: Could not open requirements file: %s\n" % e)
            i += 2
            continue
        if a in with_value:
            i += 2
            continue
        if not a.startswith("-"):
            names.append(a)
        i += 1
    return names


def _satisfies(dist, spec):
    """Whether the built-in version meets a pinned spec ("torch==2.1")."""
    try:
        from packaging.requirements import Requirement
        req = Requirement(spec)
        return not req.specifier or req.specifier.contains(dist.version, prereleases=True)
    except Exception:
        return True


def _network(verb, args):
    dists = installed()
    if verb == "install":
        missing = []
        specs = _requested(args)
        if not specs:
            sys.stderr.write('ERROR: You must give at least one requirement to install (see "pip help install")\n')
            return 1
        for spec in specs:
            bare = re.split(r"[\[<>=!~;@ ]", spec, 1)[0]
            d = dists.get(_canon(bare))
            if d is not None and not _satisfies(d, spec):
                d = None          # a different version than the one built in
            if d is not None:
                print("Requirement already satisfied: %s %s (built into BenchCode)"
                      % (d.metadata["Name"], d.version))
            else:
                missing.append(spec)
        if missing:
            print("pip can't download %s: %s" % (", ".join(missing), _OFFLINE_LINE))
            return 1
        return 0
    print("pip %s isn't available: %s" % (verb, _OFFLINE_LINE))
    return 1


# ─── entry point ──────────────────────────────────────────────────

_USAGE = """Usage:
  pip <command> [options]

Commands that work here (BenchCode reads the built-in packages; no internet needed):
  list                        List installed packages.
  show <package> [...]        Show information about installed packages (-f lists files).
  freeze                      Output installed packages in requirements format.
  check                       Verify installed packages have compatible dependencies.

Not available (they download or remove code):
  install, download, wheel, uninstall, index, search

BenchCode's packages come built in and work offline; Library lists every one."""


def main(argv=None):
    """Run one pip command line (without the leading 'pip'). Prints like pip
    and returns its exit code."""
    args = list(sys.argv[1:] if argv is None else argv)
    # Global options pip takes before the verb.
    while args and args[0] in ("-q", "--quiet", "-v", "--verbose", "--no-color", "--isolated",
                               "--disable-pip-version-check", "--no-cache-dir", "--no-input"):
        args.pop(0)
    if not args or args[0] in ("help", "-h", "--help", "-H", "--h", "-help", "-?", "/?"):
        print(_USAGE)
        return 0
    if args[0] in ("-V", "--version", "version"):
        print("pip (BenchCode offline: list, show, freeze and check read the built-in packages; "
              "Python %d.%d)" % sys.version_info[:2])
        return 0
    verb, rest = args[0], args[1:]
    if any(a in ("-h", "--help") for a in rest):
        print(_USAGE)
        return 0
    if verb == "list":
        return _list(rest)
    if verb == "freeze":
        return _freeze(rest)
    if verb == "show":
        return _show(rest)
    if verb == "check":
        return _check(rest)
    if verb == "uninstall":
        print("pip uninstall isn't available here: BenchCode's packages are built into the app "
              "and can't be removed.")
        return 1
    if verb in _NETWORK_VERBS:
        return _network(verb, rest)
    if verb in ("cache", "config", "debug", "hash", "completion", "inspect"):
        print("pip %s isn't part of BenchCode's offline pip. %s" % (verb, "Try pip list or pip show."))
        return 1
    sys.stderr.write('ERROR: unknown command "%s"\n' % verb)
    return 1


if __name__ == "__main__":
    sys.exit(main())
